import heapq
from collections import Counter


def least_interval(tasks, n):
    heap = [-count for count in Counter(tasks).values()]   # max-heap via negated counts
    heapq.heapify(heap)
    time = 0
    while heap:
        ran = []
        for _ in range(n + 1):          # one cycle: up to n + 1 different tasks
            if heap:
                ran.append(heapq.heappop(heap) + 1)    # run it once (counts are negative)
        for left in ran:
            if left < 0:
                heapq.heappush(heap, left)
        time += n + 1 if heap else len(ran)            # the last cycle needs no idle tail
    return time

