import heapq


def median_ops(ops):
    low = []                            # max-heap (negated values): the smaller half
    high = []                           # min-heap: the larger half
    out = []
    for op in ops:
        if op[0] == "add":
            heapq.heappush(low, -op[1])
            heapq.heappush(high, -heapq.heappop(low))   # the largest of the small half moves up
            if len(high) > len(low):                    # keep low equal or one bigger
                heapq.heappush(low, -heapq.heappop(high))
        else:
            if len(low) > len(high):
                out.append(-low[0])
            else:
                out.append((-low[0] + high[0]) / 2)
    return out
